  ('acad-eng-001', 1, 'in_review', array['pre_university','undergraduate']::text[], 'academic_english', 'Academic style', 'Formality', 1, 'evaluate', 'mcq', 'Which sentence is most suitable for an academic report?', '[{"id":"a","text":"The results indicate a significant increase in sales."},{"id":"b","text":"The results show sales took a big jump."},{"id":"c","text":"Sales went up loads, as you can see."},{"id":"d","text":"It''s pretty clear stuff sold way more."}]'::jsonb, null, 'Use an appropriate academic register.', 'Academic English for pre-university and first-year study (e.g. MUET / EAP, CEFR B2–C1).', 'Eduventure (original questions)', 'CC BY 4.0'),
  ('acad-eng-002', 1, 'in_review', array['pre_university','undergraduate']::text[], 'academic_english', 'Essay writing', 'Thesis statements', 1, 'remember', 'mcq', 'What is a thesis statement?', '[{"id":"a","text":"A sentence that states the main argument of an essay"},{"id":"b","text":"The list of sources at the end of an essay"},{"id":"c","text":"The title of the essay"},{"id":"d","text":"A summary of the evidence in each paragraph"}]'::jsonb, null, 'Recognise the purpose of a thesis statement.', 'Academic English: essay writing (e.g. MUET / EAP).', 'Eduventure (original questions)', 'CC BY 4.0'),
