insert into public.question_keys (question_id, answer, explanation, wrong, mistakes) values
  ('acad-eng-001', '"a"'::jsonb, 'Academic writing uses precise, formal vocabulary (indicate, significant) and avoids slang, contractions and addressing the reader.', '{"b":"\"Took a big jump\" is informal.","c":"\"Loads\" is slang, and \"as you can see\" addresses the reader directly.","d":"Contractions (it''s) and slang (pretty, stuff, way more) are too informal."}'::jsonb, null),
  ('acad-eng-002', '"a"'::jsonb, 'The thesis statement, usually at the end of the introduction, tells the reader the essay''s central claim.', '{"b":"That is the reference list or bibliography.","c":"A title names the topic; the thesis states your position on it.","d":"Summaries of evidence belong in body paragraphs or the conclusion."}'::jsonb, null),
  ('acad-eng-003', '["a","b","d"]'::jsonb, 'Hedging softens claims to match the strength of the evidence: may suggest, it is possible that, appears to.', '{"c":"\"Proves beyond doubt\" is a very strong claim, the opposite of hedging.","e":"\"Definitely\" expresses certainty, not caution."}'::jsonb, null),
  ('acad-eng-004', '["d","b","a","c"]'::jsonb, 'Introduction (with thesis) → body paragraphs (arguments and evidence) → conclusion → reference list.', null, null),
  ('acad-eng-005', '"true"'::jsonb, 'The idea still belongs to the original author. Citing gives them credit and avoids plagiarism, whether you quote or paraphrase.', '{"false":"Changing the words does not make the idea yours: any borrowed idea needs a citation."}'::jsonb, null),
  ('acad-eng-006', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Plagiarism is passing off others'' work as yours. Paraphrasing and quoting are both acceptable when cited.', null, null),
  ('acad-eng-007', '"a"'::jsonb, 'A topic sentence states the paragraph''s main idea clearly and covers what the paragraph will discuss.', '{"b":"A personal anecdote is too narrow to introduce the paragraph''s main idea.","c":"Preferences between sports are off the topic of benefits.","d":"A single word is not a sentence and makes no point."}'::jsonb, null),
  ('acad-eng-008', '{"accept":["reference list","references","the reference list"]}'::jsonb, 'APA uses a "References" list: every source cited in the text appears there, in alphabetical order by author.', null, null),
  ('ug-res-001', '"a"'::jsonb, 'The independent variable is manipulated by the researcher to see its effect on the dependent variable.', '{"b":"The measured variable is the dependent variable.","c":"Variables kept the same are control variables.","d":"An unwanted factor that affects results is a confounding variable."}'::jsonb, null),
  ('ug-res-002', '"a"'::jsonb, 'Qualitative data describe qualities in words, images or themes rather than numbers.', '{"b":"Reaction times are numerical: quantitative data.","c":"Scores are numerical: quantitative data.","d":"Heights are measurements: quantitative data."}'::jsonb, null),
  ('ug-res-003', '"true"'::jsonb, 'Sampling error shrinks as the sample grows (the standard error falls with √n), so estimates become more precise. A biased sampling method stays biased, however large.', '{"false":"Random samples vary less from the population value as they get bigger; that is why larger studies give narrower confidence intervals."}'::jsonb, null),
  ('ug-res-004', '["a","b","d"]'::jsonb, 'Random allocation makes the groups similar, the control group provides a comparison, and outcomes are compared to estimate the effect.', '{"c":"Letting participants choose introduces selection bias; random allocation avoids this."}'::jsonb, null),
  ('ug-res-005', '["b","d","a","e","c"]'::jsonb, 'Question → literature review → data collection → analysis → reporting.', null, null),
  ('ug-res-006', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Random sampling gives everyone an equal chance; stratified sampling ensures each subgroup is represented; convenience sampling is quick but often biased.', null, null),
  ('ug-res-007', '"a"'::jsonb, 'A reliable measure gives similar results under the same conditions, across time or across raters.', '{"b":"That is validity.","c":"That is generalisability (external validity).","d":"That is research ethics, not reliability."}'::jsonb, null),
  ('ug-bus-001', '["a","b"]'::jsonb, 'Opportunities and threats come from the outside environment (markets, competitors, laws).', '{"c":"Strengths are internal: things the business itself does well.","d":"Weaknesses are internal: things the business itself does poorly."}'::jsonb, null),
  ('ug-bus-002', '"a"'::jsonb, 'The 4 Ps are product, price, place and promotion. People was added later in the extended 7 Ps for services.', '{"b":"Product is one of the 4 Ps.","c":"Place (distribution) is one of the 4 Ps.","d":"Promotion is one of the 4 Ps."}'::jsonb, null),
  ('ug-bus-003', '{"value":1000,"tolerance":0,"unit":"units"}'::jsonb, 'Contribution per unit = 25 − 15 = RM10. Break-even = fixed costs ÷ contribution = 10,000 ÷ 10 = 1,000 units.', null, '[{"value":400,"why":"Divide by the contribution (price − variable cost), not the price."},{"value":667,"why":"Use the contribution per unit (RM10), not the variable cost."}]'::jsonb),
  ('ug-bus-004', '{"value":15,"tolerance":0,"unit":"%"}'::jsonb, 'Net profit margin = net profit ÷ revenue × 100 = 30,000 ÷ 200,000 × 100 = 15%.', null, '[{"value":6.67,"why":"That is revenue ÷ profit; put profit on top."}]'::jsonb),
  ('ug-bus-005', '"true"'::jsonb, 'A sole proprietorship is not a separate legal entity, so the owner''s personal assets can be used to pay business debts.', '{"false":"Limited liability comes with forming a company (e.g. Sdn Bhd). A sole proprietor and the business are legally the same person."}'::jsonb, null),
  ('ug-bus-006', '{"a":"y","b":"z","c":"x"}'::jsonb, 'Planning sets the direction, organising arranges the resources, controlling checks progress and corrects it.', null, null),
  ('ug-bus-007', '["b","d","a","c"]'::jsonb, 'Introduction (launch), growth (sales rise fast), maturity (sales level off), decline (sales fall).', null, null),
  ('ug-bus-008', '{"accept":["vertical integration","backward vertical integration","backward integration"]}'::jsonb, 'Joining with a business at a different stage of the same supply chain is vertical integration. Buying a supplier is backward vertical integration.', null, null),
  ('preu-env-001', '"a"'::jsonb, 'Burning coal, oil and gas releases carbon dioxide, the main driver of human-caused global warming.', '{"b":"Oxygen is used up in burning, not released, and it is not a greenhouse gas.","c":"Nitrogen makes up most of the air but is not a greenhouse gas.","d":"Argon is an unreactive gas, not a greenhouse gas."}'::jsonb, null),
  ('preu-env-002', '"true"'::jsonb, 'Stratospheric ozone absorbs most of the Sun''s harmful UV-B and UV-C radiation, which can damage DNA.', '{"false":"Ozone''s key role is absorbing UV radiation. Its thinning raised skin-cancer risk, leading to the Montreal Protocol."}'::jsonb, null),
  ('preu-env-003', '["a","b","d"]'::jsonb, 'Eutrophication is caused by excess nutrients (nitrates and phosphates), which trigger algal blooms that use up oxygen when they decay.', '{"c":"Riverbank trees help prevent eutrophication by absorbing nutrients and reducing run-off."}'::jsonb, null),
  ('preu-env-004', '["b","d","a","e","c"]'::jsonb, 'Organism → population (one species) → community (all species) → ecosystem (community plus environment) → biosphere (all ecosystems on Earth).', null, null),
  ('preu-env-005', '"a"'::jsonb, 'Biodiversity includes the variety of species, genes and ecosystems in an area.', '{"b":"Biomass is the total mass of living material.","c":"Population density is the number of individuals per unit area.","d":"Carrying capacity is the largest population an environment can support."}'::jsonb, null),
  ('preu-env-006', '{"a":"y","b":"z","c":"x"}'::jsonb, 'CFCs break down ozone; sulphur dioxide dissolves in rain to form acids; carbon dioxide traps heat in the atmosphere.', null, null),
  ('preu-env-007', '{"value":1000,"tolerance":0,"unit":"kJ"}'::jsonb, 'Only about 10% of energy passes to the next trophic level; the rest is lost as heat, movement and waste. 10% of 10,000 = 1,000 kJ.', null, '[{"value":100,"why":"100 kJ would reach the secondary consumers, two levels up."},{"value":9000,"why":"9,000 kJ is the energy lost, not the energy passed on."}]'::jsonb),
  ('ug-sec-001', '"a"'::jsonb, 'Phishing uses messages that pretend to come from trusted sources to steal passwords, card numbers or other data.', '{"b":"That is ransomware.","c":"That is a denial-of-service attack.","d":"That is a brute-force attack."}'::jsonb, null),
  ('ug-sec-002', '["a","b"]'::jsonb, 'Password managers make unique, strong passwords practical, and two-factor authentication protects accounts even if a password leaks.', '{"c":"If one site is breached, a reused password unlocks all your other accounts.","d":"Passwords should never be shared; anyone who has it can act as you."}'::jsonb, null),
  ('ug-sec-003', '"true"'::jsonb, 'HTTPS uses TLS to encrypt traffic, so others on the network cannot read or change it. It does not prove the website itself is honest.', '{"false":"The S stands for secure: HTTPS wraps HTTP in TLS encryption."}'::jsonb, null),
  ('ug-sec-004', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Ransomware holds data hostage; DDoS overwhelms a service; SQL injection abuses unchecked input to run database commands.', null, null),
  ('ug-sec-005', '"a"'::jsonb, 'Two-factor authentication combines different kinds of factor: something you know (password) and something you have (your phone).', '{"b":"Both are something you know, so this is one factor used twice.","c":"A username is not secret; only the password is a factor.","d":"Both are something you know: still a single factor type."}'::jsonb, null),
  ('ug-sec-006', '{"accept":["least privilege","principle of least privilege","the principle of least privilege"]}'::jsonb, 'The principle of least privilege limits the damage if an account is misused or compromised.', null, null),
  ('ug-ai-001', '"a"'::jsonb, 'Supervised learning trains on input–output pairs, such as photos labelled "cat" or "dog".', '{"b":"Unsupervised learning finds patterns in unlabelled data.","c":"Reinforcement learning learns from rewards gained by acting in an environment.","d":"Clustering is an unsupervised technique: it groups unlabelled data."}'::jsonb, null),
  ('ug-ai-002', '"true"'::jsonb, 'An overfitted model has learned noise and quirks of the training set instead of the general pattern, so it does not generalise.', '{"false":"That is exactly overfitting. Doing poorly on both training and new data is underfitting."}'::jsonb, null),
  ('ug-ai-003', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Regression predicts numbers, classification predicts categories, and clustering finds groups without labels.', null, null),
  ('ug-ai-004', '["a","b","d"]'::jsonb, 'More data, regularisation (penalising complexity) and early stopping (halting before the model memorises the training set) all improve generalisation.', '{"c":"More parameters make a model more flexible, which usually increases overfitting."}'::jsonb, null),
  ('ug-ai-005', '"a"'::jsonb, 'The agent tries actions, receives rewards or penalties, and learns a policy that maximises long-term reward.', '{"b":"Labelled examples are used in supervised learning.","c":"Clustering unlabelled data is unsupervised learning.","d":"Hand-written rules describe classic expert systems, not learning."}'::jsonb, null),
  ('ug-ai-006', '{"value":75,"tolerance":0,"unit":"%"}'::jsonb, 'Accuracy = correct ÷ total × 100 = 90 ÷ 120 × 100 = 75%.', null, '[{"value":25,"why":"25% is the error rate (30 wrong out of 120)."}]'::jsonb),
  ('ug-ph-001', '"a"'::jsonb, 'When enough people are immune, a disease cannot spread easily, which protects those who cannot be vaccinated, such as newborns.', '{"b":"Herd immunity is about population-level protection, not animals.","c":"That is innate immunity.","d":"Lifelong immunity in one person is individual immunity, not herd immunity."}'::jsonb, null),
  ('ug-ph-002', '{"value":22.9,"tolerance":0.1}'::jsonb, 'BMI = mass ÷ height² = 70 ÷ (1.75 × 1.75) = 70 ÷ 3.0625 ≈ 22.9.', null, '[{"value":40,"why":"Divide by height squared, not height: 70 ÷ 1.75 = 40."}]'::jsonb),
  ('ug-ph-003', '"false"'::jsonb, 'Antibiotics work against bacteria, not viruses. Using them for colds does not help and contributes to antibiotic resistance.', '{"true":"Viruses lack the structures antibiotics target. Colds and flu are viral, so antibiotics do not treat them."}'::jsonb, null),
  ('ug-ph-004', '["a","b","e"]'::jsonb, 'Modifiable risk factors are ones a person can change: smoking, activity level and diet.', '{"c":"Age cannot be changed: it is a non-modifiable risk factor.","d":"Family history cannot be changed: it is non-modifiable."}'::jsonb, null),
  ('ug-ph-005', '{"a":"z","b":"x","c":"y"}'::jsonb, 'Dengue is spread by Aedes mosquitoes, cholera by contaminated water or food, and influenza by droplets from coughs and sneezes.', null, null),
  ('ug-ph-006', '"a"'::jsonb, 'Incidence counts new cases over time, showing how fast a disease is spreading.', '{"b":"That is prevalence: all current cases, new and old.","c":"Deaths are measured by mortality.","d":"Recoveries are not what incidence measures."}'::jsonb, null),
  ('ug-ph-007', '["b","d","e","a","c"]'::jsonb, 'Wet, soap, scrub for at least 20 seconds, rinse, dry. Scrubbing long enough is what removes most germs.', null, null),
  ('ug-ph-008', '{"accept":["pandemic","a pandemic"]}'::jsonb, 'A pandemic is an epidemic that has spread internationally, such as COVID-19.', null, null)
